<?php
require_once __DIR__.'/../app/bootstrap_financial.php';redirectIfNotLoggedIn();if(!hasRole('super_admin','credit_officer')){http_response_code(403);exit('Credit operations permission required.');}$error='';$success='';$service=new CreditService($pdo);if($_SERVER['REQUEST_METHOD']==='POST'){try{requireCsrf();$approved=null;if(($_POST['decision']??'')==='approved')$approved=Money::fromDecimal($_POST['approved_amount']??'');$service->decide((int)($_POST['application_id']??0),(int)$_SESSION['user_id'],$_POST['decision']??'',$approved,$_POST['note']??'');$success='Credit decision recorded.';}catch(Throwable $e){$error=$e->getMessage();}}$stmt=$pdo->query('SELECT ca.*,u.full_name,u.email FROM credit_applications ca JOIN users u ON u.user_id=ca.user_id ORDER BY FIELD(ca.status,\'under_review\',\'needs_information\',\'approved\',\'rejected\',\'accepted\'),ca.created_at DESC');$applications=$stmt->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Credit applications | Valtoria Operations</title><link rel="stylesheet" href="../assets/css/customer-app.css"></head><body><main class="app-content"><div class="actions"><a href="dashboard.php">← Operations overview</a></div><h1>Credit applications</h1><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><?php if($success):?><div class="notice success"><?=e($success)?></div><?php endif?><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Requested</th><th>Term</th><th>Rate</th><th>Purpose</th><th>Status</th><th>Decision</th></tr></thead><tbody><?php foreach($applications as $a):?><tr><td><?=e($a['full_name'])?><br><small><?=e($a['email'])?></small></td><td class="money"><?=Money::format((int)$a['requested_amount_cents'])?></td><td><?=e($a['term_months'])?> mo</td><td><?=number_format(((int)$a['annual_rate_basis_points'])/100,2)?>%</td><td><?=e($a['purpose'])?></td><td><span class="badge <?=e($a['status'])?>"><?=e(str_replace('_',' ',$a['status']))?></span></td><td><?php if($a['status']==='under_review'):?><form method="post" class="form-grid"><?=csrfField()?><input type="hidden" name="application_id" value="<?=e($a['application_id'])?>"><div class="field"><select name="decision" required><option value="approved">Approve</option><option value="needs_information">Needs information</option><option value="rejected">Reject</option></select></div><div class="field"><input name="approved_amount" placeholder="Approved USD"></div><div class="field full"><input name="note" maxlength="1000" placeholder="Decision note"><button class="button button-primary">Record decision</button></div></form><?php else:?>Reviewed<?php endif?></td></tr><?php endforeach?></tbody></table></div></section></main></body></html>
